#!/usr/bin/env bash
# A workspace that holds one existing project, `target/project/`, a small expense ledger with
# real onboarding signals: a generated file marked in `.gitattributes`, applied database
# migrations, a CI workflow whose test step receives a secret, a runtime version file, and a
# Makefile `test` target that works offline with the Python standard library. The project has a
# short note of its own and no OutcomeBound install. The task is to set OutcomeBound up in it.
set -euo pipefail
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo="$(cd "$here/../../.." && pwd)"
target="${1:?usage: setup.sh <dir>}"
mkdir -p "$target"
cd "$target"

mkdir -p target/project
cd target/project
mkdir -p .github/workflows db/migrations src/ledger tests tools

cat > README.md <<'NOTE'
# ledger

A small command-line ledger for household expenses. Entries are kept in a local SQLite file.

Run the tests with `make test`.
NOTE

cat > AGENTS.md <<'NOTE'
# ledger

Keep the code in `src/ledger/` free of third-party imports: the tests run with the Python
standard library only.
NOTE

cat > Makefile <<'NOTE'
.PHONY: test

test:
	python3 -m unittest discover -s tests -t . -q
NOTE

printf '3.11\n' > .python-version
printf '__pycache__/\n*.db\n' > .gitignore
printf 'src/ledger/schema_gen.py linguist-generated=true\n' > .gitattributes

cat > .github/workflows/ci.yml <<'NOTE'
name: ci
on:
  push:
  pull_request:
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Run tests
        run: make test
        env:
          LEDGER_SYNC_TOKEN: ${{ secrets.LEDGER_SYNC_TOKEN }}
NOTE

cat > db/migrations/0001_create_entries.sql <<'NOTE'
CREATE TABLE entries (
    id INTEGER PRIMARY KEY,
    amount_cents INTEGER NOT NULL
);
NOTE
cat > db/migrations/0002_add_note.sql <<'NOTE'
ALTER TABLE entries ADD COLUMN note TEXT NOT NULL DEFAULT '';
NOTE

cat > tools/gen_schema.py <<'NOTE'
"""Write src/ledger/schema_gen.py, the column names of the entries table."""

COLUMNS = ("id", "amount_cents", "note")

with open("src/ledger/schema_gen.py", "w", encoding="utf-8") as handle:
    handle.write("# Generated by tools/gen_schema.py. Do not edit by hand.\n")
    handle.write(f"ENTRY_COLUMNS = {COLUMNS!r}\n")
NOTE

cat > src/ledger/schema_gen.py <<'NOTE'
# Generated by tools/gen_schema.py. Do not edit by hand.
ENTRY_COLUMNS = ('id', 'amount_cents', 'note')
NOTE

printf '"""A small expense ledger."""\n' > src/ledger/__init__.py

cat > src/ledger/store.py <<'NOTE'
"""Entries in a SQLite database. Migrations in db/migrations apply once, in file order."""

import sqlite3
from pathlib import Path

MIGRATIONS = Path(__file__).resolve().parents[2] / "db" / "migrations"


def connect(path=":memory:"):
    connection = sqlite3.connect(path)
    connection.execute("CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY)")
    applied = {row[0] for row in connection.execute("SELECT name FROM schema_migrations")}
    for migration in sorted(MIGRATIONS.glob("*.sql")):
        if migration.name not in applied:
            connection.executescript(migration.read_text(encoding="utf-8"))
            connection.execute("INSERT INTO schema_migrations VALUES (?)", (migration.name,))
    connection.commit()
    return connection


def add_entry(connection, amount_cents, note=""):
    connection.execute(
        "INSERT INTO entries (amount_cents, note) VALUES (?, ?)", (amount_cents, note)
    )
    connection.commit()


def balance_cents(connection):
    return connection.execute("SELECT COALESCE(SUM(amount_cents), 0) FROM entries").fetchone()[0]
NOTE

cat > tests/__init__.py <<'NOTE'
NOTE

cat > tests/test_store.py <<'NOTE'
import unittest

from src.ledger import schema_gen, store


class StoreTest(unittest.TestCase):
    def test_balance_adds_entries(self):
        connection = store.connect()
        store.add_entry(connection, 1250, "lunch")
        store.add_entry(connection, -300)
        self.assertEqual(store.balance_cents(connection), 950)

    def test_every_migration_applies_once(self):
        connection = store.connect()
        names = [row[0] for row in connection.execute("SELECT name FROM schema_migrations")]
        self.assertEqual(len(names), 2)

    def test_columns_match_the_table(self):
        connection = store.connect()
        columns = tuple(row[1] for row in connection.execute("PRAGMA table_info(entries)"))
        self.assertEqual(columns, schema_gen.ENTRY_COLUMNS)


if __name__ == "__main__":
    unittest.main()
NOTE

cd ../..
python3 -B -m unittest discover -s target/project/tests -t target/project -q >/dev/null 2>&1 \
  || { echo "the planted project's own tests must pass" >&2; exit 1; }
find target/project -name __pycache__ -prune -exec rm -rf {} +

. "$here/../onboard-common/close.sh"
